"use client";

import { useState } from "react";

type Status = "idle" | "submitting" | "success" | "error";

export default function ContactForm() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [message, setMessage] = useState("");
  const [status, setStatus] = useState<Status>("idle");
  const [error, setError] = useState("");

  function validate(): string | null {
    if (!name.trim()) return "Please enter your name.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return "Please enter a valid email.";
    if (!message.trim()) return "Please enter a message.";
    return null;
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const v = validate();
    if (v) { setStatus("error"); setError(v); return; }
    setStatus("submitting"); setError("");
    try {
      const res = await fetch("/api/leads", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, email, message }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || "Submission failed.");
      }
      setStatus("success");
      setName(""); setEmail(""); setMessage("");
    } catch (err) {
      setStatus("error");
      setError(err instanceof Error ? err.message : "Something went wrong.");
    }
  }

  if (status === "success") {
    return (
      <div role="status" style={{ padding: "1rem", border: "1px solid #c3e6cb", background: "#f3fbf5", borderRadius: 8 }}>
        Thanks — your message has been received. We&apos;ll be in touch shortly.
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate style={{ display: "grid", gap: "1rem" }}>
      <label style={{ display: "grid", gap: ".35rem" }}>
        <span>Name</span>
        <input value={name} onChange={(e) => setName(e.target.value)} name="name" autoComplete="name" required
               style={{ padding: ".6rem", borderRadius: 6, border: "1px solid #ccc" }} />
      </label>
      <label style={{ display: "grid", gap: ".35rem" }}>
        <span>Email</span>
        <input value={email} onChange={(e) => setEmail(e.target.value)} name="email" type="email" autoComplete="email" required
               style={{ padding: ".6rem", borderRadius: 6, border: "1px solid #ccc" }} />
      </label>
      <label style={{ display: "grid", gap: ".35rem" }}>
        <span>Message</span>
        <textarea value={message} onChange={(e) => setMessage(e.target.value)} name="message" rows={5} required
                  style={{ padding: ".6rem", borderRadius: 6, border: "1px solid #ccc", resize: "vertical" }} />
      </label>
      {status === "error" && <p role="alert" style={{ color: "#b00020", margin: 0 }}>{error}</p>}
      <button type="submit" disabled={status === "submitting"}
              style={{ padding: ".75rem 1rem", borderRadius: 6, border: "none", background: "#111", color: "#fff", fontSize: "1rem", cursor: "pointer" }}>
        {status === "submitting" ? "Sending…" : "Send message"}
      </button>
    </form>
  );
}
```

